package com.oibsip.onlineexam.ui;
import javax.swing.*;import java.awt.*;
public class ProfilePanel extends JPanel {private final MainFrame f;private final JLabel username=new JLabel(),status=new JLabel(" ");private final JTextField name=new JTextField();private final JPasswordField p=new JPasswordField(),c=new JPasswordField();public ProfilePanel(MainFrame x){f=x;setLayout(new BorderLayout(20,20));JLabel h=new JLabel("Student Profile",SwingConstants.CENTER);h.setFont(new Font("SansSerif",Font.BOLD,26));add(h,BorderLayout.NORTH);JPanel form=new JPanel(new GridBagLayout());GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(10,10,10,10);g.fill=GridBagConstraints.HORIZONTAL;String[] labels={"Username","Display Name","New Password","Confirm Password"};for(int i=0;i<4;i++){g.gridx=0;g.gridy=i;form.add(new JLabel(labels[i]),g);g.gridx=1;JComponent comp=switch(i){case 0->username;case 1->name;case 2->p;default->c;};form.add(comp,g);}JButton update=new JButton("Update Profile"),start=new JButton("Start Examination"),logout=new JButton("Logout");g.gridx=1;g.gridy=4;JPanel buttons=new JPanel();buttons.add(update);buttons.add(start);buttons.add(logout);form.add(buttons,g);g.gridy=5;form.add(status,g);add(form,BorderLayout.CENTER);update.addActionListener(e->update());start.addActionListener(e->start());logout.addActionListener(e->f.logout());}public void refresh(){var u=f.session().getUser();if(u!=null){username.setText(u.getUsername());name.setText(u.getDisplayName());p.setText("");c.setText("");status.setText("Profile ready.");}}private void update(){try{f.profile().update(f.session().getUser(),name.getText(),new String(p.getPassword()),new String(c.getPassword()));status.setText("Profile updated successfully.");}catch(Exception e){JOptionPane.showMessageDialog(f,e.getMessage(),"Validation",JOptionPane.WARNING_MESSAGE);}}private void start(){if(f.session().getUser().getDisplayName().isBlank()){JOptionPane.showMessageDialog(f,"Please complete your profile first.");return;}f.show(MainFrame.EXAM);}}
